function serializeOptions(options) {
  if (
    options === null ||
    typeof options !== "object" ||
    (Object.getPrototypeOf(options) !== Object.prototype &&
      Object.getPrototypeOf(options) !== null)
  ) {
    throw new TypeError("options must be a plain object");
  }

  const pairs = [];

  for (const name of Object.keys(options)) {
    const value = options[name];
    if (value === undefined) continue;

    let stringValue;
    if (value === null) {
      stringValue = "";
    } else if (typeof value === "string") {
      stringValue = value;
    } else if (typeof value === "number") {
      if (!Number.isFinite(value)) {
        throw new TypeError("number values must be finite");
      }
      stringValue = String(value);
    } else if (typeof value === "boolean") {
      stringValue = String(value);
    } else {
      throw new TypeError("unsupported option value");
    }

    pairs.push([percentEncode(name), percentEncode(stringValue)]);
  }

  pairs.sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    if (a[1] < b[1]) return -1;
    if (a[1] > b[1]) return 1;
    return 0;
  });

  return pairs.map(pair => pair[0] + "=" + pair[1]).join("&");
}

function percentEncode(value) {
  const hex = "0123456789ABCDEF";
  let result = "";

  for (let i = 0; i < value.length; i++) {
    let codePoint = value.charCodeAt(i);

    if (codePoint >= 0xD800 && codePoint <= 0xDBFF) {
      if (i + 1 >= value.length) throw new URIError("lone surrogate");
      const low = value.charCodeAt(++i);
      if (low < 0xDC00 || low > 0xDFFF) {
        throw new URIError("lone surrogate");
      }
      codePoint =
        0x10000 + ((codePoint - 0xD800) << 10) + (low - 0xDC00);
    } else if (codePoint >= 0xDC00 && codePoint <= 0xDFFF) {
      throw new URIError("lone surrogate");
    }

    if (
      (codePoint >= 0x41 && codePoint <= 0x5A) ||
      (codePoint >= 0x61 && codePoint <= 0x7A) ||
      (codePoint >= 0x30 && codePoint <= 0x39) ||
      codePoint === 0x2D ||
      codePoint === 0x2E ||
      codePoint === 0x5F ||
      codePoint === 0x7E
    ) {
      result += String.fromCharCode(codePoint);
    } else if (codePoint <= 0x7F) {
      result += "%" + hex[codePoint >> 4] + hex[codePoint & 0x0F];
    } else if (codePoint <= 0x7FF) {
      result += utf8Byte(0xC0 | (codePoint >> 6), hex);
      result += utf8Byte(0x80 | (codePoint & 0x3F), hex);
    } else if (codePoint <= 0xFFFF) {
      result += utf8Byte(0xE0 | (codePoint >> 12), hex);
      result += utf8Byte(0x80 | ((codePoint >> 6) & 0x3F), hex);
      result += utf8Byte(0x80 | (codePoint & 0x3F), hex);
    } else {
      result += utf8Byte(0xF0 | (codePoint >> 18), hex);
      result += utf8Byte(0x80 | ((codePoint >> 12) & 0x3F), hex);
      result += utf8Byte(0x80 | ((codePoint >> 6) & 0x3F), hex);
      result += utf8Byte(0x80 | (codePoint & 0x3F), hex);
    }
  }

  return result;
}

function utf8Byte(byte, hex) {
  return "%" + hex[byte >> 4] + hex[byte & 0x0F];
}
